    """The delay a response asks for before a retry, in seconds, if any."""
    header = response.headers.get("retry-after-ms")
    if header is not None:
        try:
            return float(header) / 1000
        except ValueError:
            pass
    header = response.headers.get("retry-after")
    if header is None:
        return None
    try:
        return float(header)
    except ValueError:
        pass
